/**
 * 将 Alias / 输入 ID 解析为 Contact.UserName（踢人必须用 UserName）
 */
export function resolveContactUserName(id) {
    const q = sqlEscape(id);
    // 1) 已是 UserName
    let rows = execDbQuery('MicroMsg.db', `SELECT UserName, Alias, NickName FROM Contact WHERE UserName='${q}' LIMIT 1;`);
    if (rows.length > 0) {
        const userName = rowText(rows[0], 'UserName');
        if (userName) {
            return userName;
        }
    }
    // 2) Alias（微信号）
    rows = execDbQuery('MicroMsg.db', `SELECT UserName, Alias FROM Contact WHERE Alias='${q}' LIMIT 1;`);
    if (rows.length > 0) {
        const userName = rowText(rows[0], 'UserName');
        if (userName) {
            console.log(`resolveContactUserName: Alias ${id} -> UserName ${userName}`);
            return userName;
        }
    }
    // 3) Remark / NickName（兜底，可能重名）
    rows = execDbQuery('MicroMsg.db', `SELECT UserName, NickName, Remark FROM Contact WHERE Remark='${q}' OR NickName='${q}' LIMIT 2;`);
    if (rows.length === 1) {
        const userName = rowText(rows[0], 'UserName');
        if (userName) {
            console.log(`resolveContactUserName: Nick/Remark ${id} -> UserName ${userName}`);
            return userName;
        }
    }
    console.warn(`resolveContactUserName: 未解析到 UserName，沿用原值: ${id}`);
    return id;
}
/** 读取群成员 UserName 列表（ChatRoom.UserNameList 分隔符为 ^G 或 \\x07） */
export function getRoomMemberUserNames(roomId) {
    const rows = execDbQuery('MicroMsg.db', `SELECT UserNameList FROM ChatRoom WHERE ChatRoomName='${sqlEscape(roomId)}' LIMIT 1;`);
    if (rows.length === 0) {
        return [];
    }
    const list = rowText(rows[0], 'UserNameList');
    if (!list) {
        return [];
    }
    // 微信库常见：id1^Gid2^Gid3（字面 ^G）或 id1\x07id2（ASCII BEL）
    // 切勿只按 ^ 分割，否则后续成员会残留前缀 G（如 Gtyutluyc）
    return list
        .split(/\^G|\x07/)
        .map(s => s.replace(/^[G\^;,\s]+|[;,\s]+$/g, '').trim())
        .filter(Boolean);
}
