    const addAddr = moduleBaseAddress.add(offsets.kAddChatroomMember);
    const GetChatRoomMgr = new NativeFunction(moduleBaseAddress.add(offsets.kChatRoomMgr), 'pointer', []);
    const AddChatroomMember = new NativeFunction(addAddr, 'int', ['pointer', 'pointer', 'pointer', 'pointer']);
    const mgrPtr = GetChatRoomMgr();
    if (!mgrPtr || mgrPtr.isNull()) {
        throw new Error('GetChatRoomMgr 返回空指针');
    }
