/** ChatRoom.DisplayNameList 与 UserNameList 一一对应（群内昵称） */
function getRoomMemberDisplayNames(roomId) {
    try {
        const rows = execDbQuery('MicroMsg.db', `SELECT DisplayNameList FROM ChatRoom WHERE ChatRoomName='${sqlEscape(roomId)}' LIMIT 1;`);
        if (rows.length === 0) {
            return [];
        }
        const list = rowText(rows[0], 'DisplayNameList');
        if (!list) {
            return [];
        }
        return list
            .split(/\^G|\x07/)
            .map(s => s.replace(/^[G\^;,\s]+|[;,\s]+$/g, '').trim());
    }
    catch (e) {
        return [];
    }
}
function lookupContactBrief(wxid) {
    const empty = { alias: '', name: '', remark: '', bigHeadImgUrl: '', smallHeadImgUrl: '' };
    try {
        const rows = execDbQuery('MicroMsg.db', `SELECT UserName, Alias, NickName, Remark, BigHeadImgUrl, SmallHeadImgUrl ` +
            `FROM Contact WHERE UserName='${sqlEscape(wxid)}' LIMIT 1;`);
        if (rows.length === 0) {
            return empty;
        }
        const r = rows[0];
        return {
            alias: rowText(r, 'Alias'),
            name: rowText(r, 'NickName'),
            remark: rowText(r, 'Remark'),
            bigHeadImgUrl: rowText(r, 'BigHeadImgUrl'),
            smallHeadImgUrl: rowText(r, 'SmallHeadImgUrl'),
        };
    }
    catch (e) {
        return empty;
    }
}
